def Match(self, registry_key):
    """Determines if a Windows Registry key matches the filter.

    Args:
      registry_key (dfwinreg.WinRegistryKey): Windows Registry key.

    Returns:
      bool: True if the Windows Registry key matches the filter.
    """
    key_path = registry_key.path.upper()
    # Prevent this filter matching non-string MRUList values.
    for ignore_key_path_suffix in self._IGNORE_KEY_PATH_SUFFIXES:
      if key_path.endswith(ignore_key_path_suffix):
        return False

    return super(MRUListStringRegistryKeyFilter, self).Match(registry_key)

mgc_code:
def Match(self, registry_key):
    """Determines if a Windows Registry key matches the filter.

    Args:
      registry_key (dfwinreg.WinRegistryKey): Windows Registry key.

    Returns:
      bool: True if the Windows Registry key matches the filter.
    """
    if self.path_regex:
      if not self.path_regex.match(registry_key.path):
        return False

    if self.name_regex:
      if not self.name_regex.match(registry_key.name):
        return False

    if self.value_regex:
      for value_name, value_data in registry_key.GetValues():
        if not self.value_regex.match(value_name):
          continue

        if not self.value_regex.match(value_data):
          continue

        return True

    return False

