def match(tgt, delimiter=DEFAULT_TARGET_DELIM, opts=None):
    """
    Matches a grain based on regex
    """
    if not opts:
        opts = __opts__
    log.debug('grains pcre target: %s', tgt)
    if delimiter not in tgt:
        log.error('Got insufficient arguments for grains pcre match '
                  'statement from master')
        return False

    return salt.utils.data.subdict_match(
        opts['grains'], tgt, delimiter=delimiter, regex_match=True)

mgc_code:
def match(tgt, delimiter=DEFAULT_TARGET_DELIM, opts=None):
    """
    Matches a grain based on regex
    """
    if not opts:
        opts = {}
    if not tgt:
        return False
    if not delimiter:
        delimiter = DEFAULT_TARGET_DELIM
    if isinstance(tgt, str):
        tgt = tgt.split(delimiter)
    if isinstance(tgt, list):
        tgt = [x.strip() for x in tgt]
    if not isinstance(tgt, list):
        raise TypeError("tgt must be a list")
    if len(tgt) == 0:
        raise ValueError("tgt must not be empty")
    if len(tgt) == 1:
        return tgt[0]
    if len(tgt) == 2:
        if tgt[0] == "glob":
            return glob.glob(tgt[1])
        if tgt[0] == "regex":
            return re.findall(tgt[1], opts.get("regex_flags", 0))
    raise ValueError("tgt must be a list of length 1 or 2")

