mgc_code:
def parse_value_reference(self, tup_tree):
        """
        Parse a VALUE.REFERENCE element and return the instance path or class
        path it represents as a CIMInstanceName or CIMClassName object,
        respectively.

          ::

            <!ELEMENT VALUE.REFERENCE (CLASSPATH | LOCALCLASSPATH | CLASSNAME |
                                       INSTANCEPATH | LOCALINSTANCEPATH |
                                       INSTANCENAME)>
        """
        if tup_tree.tag == 'CLASSPATH':
            return CIMInstanceName(self.parse_class_path(tup_tree))
        elif tup_tree.tag == 'LOCALCLASSPATH':
            return CIMInstanceName(self.parse_local_class_path(tup_tree))
        elif tup_tree.tag == 'CLASSNAME':
            return CIMClassName(self.parse_class_name(tup_tree))
        elif tup_tree.tag == 'INSTANCEPATH':
            return CIMInstanceName(self.parse_instance_path(tup_tree))
        elif tup_tree.tag == 'LOCALINSTANCEPATH':
            return CIMInstanceName(self.parse_local_instance_path(tup_tree))
        elif tup_tree.tag == 'INSTANCENAME':
            return CIMInstanceName(self.parse_instance_name(tup_tree))
        else:
            raise CIMError(CIM_ERR_INVALID_PARAMETER,
                           'Invalid VALUE.REFERENCE tag: %s' % tup_tree.tag)

