mgc_code:
async def send_mail(self, mail):
        """Pipe the given mail to the configured sendmail command.  Display a
        short message on success or a notification on error.
        :param mail: the mail to send out
        :type mail: :class:`email.message.Message` or string
        :raises: class:`SendingMailFailed` if sending failes
        """
        if not self.sendmail_path:
            raise SendingMailFailed("No sendmail path configured")
        if not self.sendmail_args:
            raise SendingMailFailed("No sendmail arguments configured")

        if isinstance(mail, str):
            mail = email.message_from_string(mail)

        if self.debug:
            print("Sending mail to %s" % self.sendmail_path)
            print(mail.as_string())

        try:
            p = await asyncio.create_subprocess_exec(
                self.sendmail_path, *self.sendmail_args,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await p.communicate(mail.as_bytes())
            if p.returncode!= 0:
                raise SendingMailFailed(
                    "Sendmail exited with code %d: %s" % (p.returncode, stderr)
                )
        except OSError as e:
            raise SendingMailFailed(
                "Sendmail exited with code %d: %s" % (e.errno, e.strerror)
            )

