def lyricsmode(song):
    """
    Returns the lyrics found in lyricsmode.com for the specified mp3 file or an
    empty string if not found.
    """
    try:
        # Get the lyrics from the website
        url = 'http://lyricsmode.com/lyrics/' + song.artist + '/' + song.title + '.html'
        response = urllib2.urlopen(url)
        html = response.read()
        response.close()

        # Parse the html to find the lyrics
        soup = BeautifulSoup(html)
        lyrics = soup.find('div', {'class': 'lyrics'})
        if lyrics:
            return lyrics.text.strip()
        else:
            return ''
    except:
        return ''

