mgc_code:
def yank_nth_arg(self, n=None, _yank_last_arg=False):
        """
        Pick nth word from previous history entry (depending on current
        `yank_nth_arg_state`) and insert it at current position. Rotate through
        history if called repeatedly. If no `n` has been given, take the first
        argument. (The second word.)

        :param n: (None or int), The index of the word from the previous line
            to take.
        """
        if n is None:
            n = self.yank_nth_arg_state
        if n == 0:
            self.yank_nth_arg_state = 0
            return
        if n < 0:
            n = self.yank_nth_arg_state + n
        if n > 0:
            self.yank_nth_arg_state = n
        else:
            self.yank_nth_arg_state = 0
        if _yank_last_arg:
            self.yank_nth_arg_state = 0
        if self.yank_nth_arg_state == 0:
            self.yank_nth_arg_state = 1
        if self.yank_nth_arg_state > len(self.history[-1]):
            self.yank_nth_arg_state = len(self.history[-1])
        if self.yank_nth_arg_state < 0:
            self.yank_nth_arg_state = 0
        self.insert(self.history[-1][self.yank_nth_arg_state - 1])

