    if os_name:
      conditions.append(self._GetCondition('os_name', os_name))
    if cpe:
      conditions.append(self._GetCondition('cpe', cpe))
    if label:
      conditions.append(self._GetCondition('label', label))

    return self._SearchConditions(conditions)

