def authorized(self, environ):
        """
        If we're running Django and ``GNOTTY_LOGIN_REQUIRED`` is set
        to ``True``, pull the session cookie from the environment and
        validate that the user is authenticated.
        """
        if self.django_enabled:
            if self.login_required:
                if environ.get('GNOTTY_LOGIN_REQUIRED', False):
                    session_key = environ.get('GNOTTY_SESSION_KEY', None)
                    if session_key:
                        try:
                            session = self.django_session_store.get(session_key)
                            if session:
                                return session.get('user', None)
                        except Exception:
                            pass
        return None

