hwc_code:
def broadcast(self, from_client, message, valid_till=None, push_data=None):
        """
        发送广播消息，只能以系统会话名义发送。全部用户都会收到此消息，不论是否在此会话中。

        :param from_client: 发送者 id
        :param message: 消息内容
        :param valid_till: 指定广播消息过期时间
        :param puhs_data: 推送消息内容，参考：https://url.leanapp.cn/pushData
        """
        if isinstance(message, dict):
            message = json.dumps(message)
        params = {
            'from_peer': from_client,
            'conv_id': self.id,
            'message': message,
        }
        if push_data:
            params['push_data'] = push_data
        if valid_till:
            if isinstance(valid_till, datetime):
                valid_till = arrow.get(valid_till).datetime
            params['valid_till'] = valid_till
        client.post('/rtm/broadcast', params=params).json()

mgc_code:
def broadcast(self, from_client, message, valid_till=None, push_data=None):
        """
        发送广播消息，只能以系统会话名义发送。全部用户都会收到此消息，不论是否在此会话中。

        :param from_client: 发送者 id
        :param message: 消息内容
        :param valid_till: 指定广播消息过期时间
        :param puhs_data: 推送消息内容，参考：https://url.leanapp.cn/pushData
        """
        if not isinstance(message, dict):
            raise TypeError('message must be a dict')

        if not isinstance(push_data, dict) and push_data is not None:
            raise TypeError('push_data must be a dict')

        if not isinstance(valid_till, int) and valid_till is not None:
            raise TypeError('valid_till must be an int')

        if valid_till is not None:
            if valid_till < 0:
                raise ValueError('valid_till must be greater than 0')

        if push_data is not None:
            if not isinstance(push_data.get('title'), str):
                raise TypeError('push_data.title must be a string')

            if not isinstance(push_data.get('content'), str):
                raise TypeError('push_data.content must be a string')

        self.send_message(
            from_client=from_client,
            to_client=self.system_client_id,
            message=message,
            valid_till=valid_till,
            push_data=push_data
        )

