def click_table_printer(headers, _filter, data):
    """Generate space separated output for click commands."""
    if not data:
        return ""

    # Get the max length of each column
    max_lengths = [len(h) for h in headers]
    for row in data:
        for i, col in enumerate(row):
            max_lengths[i] = max(max_lengths[i], len(col))

    # Build the output
    output = ""
    for row in data:
        for i, col in enumerate(row):
            output += col.ljust(max_lengths[i]) + " "
        output += "\n"

    return output

