def send_message(self, sender, um_to_user_list, body):
        """
        Send a message from a user, to a user.

        :param sender:
            The :class:`User` which sends the message.

        :param um_to_user_list:
            A list which elements are :class:`User` to whom the message is for.

        :param message:
            String containing the message.

        """
        if not isinstance(sender, User):
            raise TypeError("sender must be a User")
        if not isinstance(um_to_user_list, list):
            raise TypeError("um_to_user_list must be a list")
        if not isinstance(body, str):
            raise TypeError("body must be a string")

        for user in um_to_user_list:
            if not isinstance(user, User):
                raise TypeError("um_to_user_list must contain only Users")

        for user in um_to_user_list:
            if user.id == sender.id:
                raise ValueError("Sender cannot send a message to himself")

        if len(um_to_user_list) == 0:
            raise ValueError("um_to_user_list must contain at least one user")

        if len(body) == 0:
            raise ValueError("body must contain at least one character")

        self.send_message_to_user(sender, um_to_user_list, body)

