def read1(self, n):
        """Read up to n bytes with at most one read() system call."""
        data = bytearray()
        while len(data) < n:
            chunk = self.read(n - len(data))
            if not chunk:
                return bytes(data)
            data.extend(chunk)
        return bytes(data)

