def load_neuron(handle, reader=None):
    """Build section trees from an h5 or swc file"""
    rdw = load_data(handle, reader)
    if isinstance(handle, StringType):
        name = os.path.splitext(os.path.basename(handle))[0]
    else:
        name = None
    return FstNeuron(rdw, name)

mgc_code:
def load_neuron(handle, reader=None):
    """Build section trees from an h5 or swc file"""
    if reader is None:
        reader = h5py.File(handle, 'r')
    if isinstance(handle, h5py.File):
        reader = handle
    if isinstance(handle, str):
        reader = h5py.File(handle, 'r')
    if isinstance(handle, h5py.Group):
        reader = handle
    if isinstance(handle, h5py.Dataset):
        reader = handle.parent
    if isinstance(reader, h5py.File):
        return Neuron(reader)
    else:
        raise TypeError('handle must be a h5py.File, h5py.Group, h5py.Dataset or str')

